// ─── File: CloningDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.cloning;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CloningDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        rajesh.addTransaction("OPENING +1000000");

        // SHALLOW clone via Object.clone — shares the transaction list (BUG).
        Account shallow = (Account) rajesh.clone();

        // DEEP copy via copy constructor — independent list (SAFE).
        Account deepCtor = new Account(rajesh);

        // DEEP copy via serialization round-trip — also independent (SAFE).
        Account deepSer = DeepCopyUtil.deepCopy(rajesh);

        // Mutate the LIVE account after taking all snapshots.
        rajesh.addTransaction("BATCH-ADJUST -50000");
        rajesh.debit(new BigDecimal("50000"));

        log.info(() -> "live Rajesh txns=" + rajesh.getTransactions().size()
                + " balance=Rs." + rajesh.getBalance());
        log.warning(() -> "SHALLOW snapshot txns=" + shallow.getTransactions().size()
                + " (corrupted: shares the list)");
        log.info(() -> "DEEP(ctor) snapshot txns=" + deepCtor.getTransactions().size()
                + " (safe)");
        log.info(() -> "DEEP(serial) snapshot txns=" + deepSer.getTransactions().size()
                + " (safe)");
    }
}

// ─── Would be in Account.java ───
class Account implements Cloneable, java.io.Serializable {
    private static final long serialVersionUID = 1L;
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private final java.util.List<String> transactions; // MUTABLE reference field

    Account(String id, String name, BigDecimal bal) {
            this.accountId = id;
            this.holderName = name
            this.balance = bal;
        this.transactions = new java.util.ArrayList<>();
    }

    // COPY CONSTRUCTOR: explicit deep copy of the mutable list.
    Account(Account other) {
        this.accountId = other.accountId;
        this.holderName = other.holderName;
        this.balance = other.balance; // BigDecimal is immutable → safe to share
        this.transactions = new java.util.ArrayList<>(other.transactions); // new list
    }

    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    void addTransaction(String t) { transactions.add(t); }
    BigDecimal getBalance() { return balance; }
    java.util.List<String> getTransactions() { return transactions; }

    // Object.clone produces a SHALLOW copy: 'transactions' reference is shared.
    @Override
    protected Object clone() throws CloneNotSupportedException {
        return super.clone(); // shallow: both objects point to SAME list
    }
}

// ─── Would be in DeepCopyUtil.java (serialization-based deep copy) ───
class DeepCopyUtil {
    // A serialization round-trip deep-copies the WHOLE object graph.
    // This is what Apache Commons SerializationUtils.clone(obj) does internally.
    @SuppressWarnings("unchecked")
    static <T extends java.io.Serializable> T deepCopy(T obj) throws Exception {
        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
        try (java.io.ObjectOutputStream out = new java.io.ObjectOutputStream(bytes)) {
            out.writeObject(obj);
        }
        try (java.io.ObjectInputStream in = new java.io.ObjectInputStream(
                new java.io.ByteArrayInputStream(bytes.toByteArray()))) {
            return (T) in.readObject();
        }
    }
}
